BLUE, GREEN, RED, DARK, MUTED, LIGHT = (colors.HexColor(c) for c in ["#2f6fdb", "#2e9e6b", "#d64545", "#1c2433", "#667085", "#eef3fc"])
W = A4[0] - 36 * mm

body = ParagraphStyle("body", fontName="DV", fontSize=9, leading=13.5, textColor=DARK, spaceAfter=5)
small = ParagraphStyle("small", parent=body, fontSize=8, leading=11.5, textColor=MUTED, spaceAfter=3)
h1 = ParagraphStyle("h1", parent=body, fontName="DV-B", fontSize=15, leading=19, textColor=BLUE, spaceBefore=10, spaceAfter=7, keepWithNext=1)
h2 = ParagraphStyle("h2", parent=body, fontName="DV-B", fontSize=10.5, leading=14, textColor=DARK, spaceBefore=8, spaceAfter=4, keepWithNext=1)
cell = ParagraphStyle("cell", parent=body, fontSize=8.3, leading=11.3, spaceAfter=0)
cellb = ParagraphStyle("cellb", parent=cell, fontName="DV-B")
cellh = ParagraphStyle("cellh", parent=cell, fontName="DV-B", textColor=colors.white)
h2n = ParagraphStyle("h2n", parent=h2, keepWithNext=0)
callout = ParagraphStyle("callout", parent=body, fontSize=8.8, leading=13, spaceAfter=0)
P = lambda t, s=body: Paragraph(t, s)

def table(rows, widths, header=True, first_bold=True):
    data = []
    for r, row in enumerate(rows):
        data.append([P(c, cellh if (header and r == 0) else (cellb if (first_bold and i == 0) else cell)) for i, c in enumerate(row)])
    t = Table(data, colWidths=[w * W for w in widths], repeatRows=1 if header else 0)
    st = [("VALIGN", (0, 0), (-1, -1), "TOP"), ("LEFTPADDING", (0, 0), (-1, -1), 5), ("RIGHTPADDING", (0, 0), (-1, -1), 5),
          ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4), ("LINEBELOW", (0, 0), (-1, -1), 0.4, colors.HexColor("#d9dee8"))]
    if header: st += [("BACKGROUND", (0, 0), (-1, 0), BLUE)]
    for r in range(1 if header else 0, len(rows)):
        if r % 2 == 0: st.append(("BACKGROUND", (0, r), (-1, r), LIGHT))
    t.setStyle(TableStyle(st)); return t

def box(text, color=BLUE, title=None):
    inner = [P(f"<b>{title}</b>", callout)] if title else []
    inner.append(P(text, callout))
    t = Table([[inner]], colWidths=[W])
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#f4f7fd") if color == BLUE else colors.HexColor("#fdf3f3") if color == RED else colors.HexColor("#f1faf5")),
                           ("LINEBEFORE", (0, 0), (0, -1), 3, color), ("LEFTPADDING", (0, 0), (-1, -1), 9), ("RIGHTPADDING", (0, 0), (-1, -1), 9),
                           ("TOPPADDING", (0, 0), (-1, -1), 6), ("BOTTOMPADDING", (0, 0), (-1, -1), 6)]))
    return t

def fig(name, caption, width=1.0):
    from PIL import Image as PI
    w, h = PI.open(f"{FIG}/{name}").size
    iw = W * width
    return KeepTogether([Image(f"{FIG}/{name}", width=iw, height=iw * h / w), P(caption, small)])

